steps.text:
/*
	VIOC_enemy_camps.sqf - agregado por tools/vio_build.py (parche enemy_camps; copia configurada, no es del autor de la
	mision). Solo servidor (init.sqf lo lanza con execVM).

	Campamentos avanzados de la IA ENEMIGA (Oeste/Este sin jugadores), estilo Reforger: un camion de su bando con tiendas,
	red de camuflaje, cajas y fogata, fuera de los caminos, cerca de uno de sus pueblos del FRENTE (400-900 m, hacia lo
	tuyo). Mientras exista, saca una escuadra de infanteria (VIOC_EC_SQUAD, de las listas de pueblo del bando, con el
	equipo de la mision) cada VIOC_ENEMY_CAMPS_EVERY min que ataca tu pueblo del frente mas cercano (a menos de 3 km; si
	no hay, patrulla alrededor del campamento).
	  - Como mucho VIOC_ENEMY_CAMPS campamentos por bando enemigo; uno nuevo cada VIOC_EC_NEW s (el primero a los 8 min).
	  - Se levanta lejos de ti: a mas de VIOC_EC_SAFE m de tus pueblos, HQ y estructuras y a mas de VIOC_EC_PLAYER_MIN m
	    de cualquier jugador.
	  - Topes: VIOC_EC_CAP soldados vivos por campamento y el presupuesto de IA de perf_cleanup (VIOC_PERF_AI_MAX menos
	    VIOC_EC_AI_MARGIN). No sale nadie con soldados tuyos a menos de VIOC_EC_NOSPAWN m, ni si el bando ya no tiene un
	    pueblo a menos de VIOC_EC_HOLD_R m o su pueblo ancla ya no es suyo o es de retaguardia (queda dormido; a los
	    VIOC_EC_DORM s dormido y sin jugadores a 1 km se quita en silencio y deja el cupo libre).
	  - DESTRUIDO = ENCONTRADO: cuando un soldado de tu bando (tu, tu grupo o la IA de tu bando, a pie) llega a menos de
	    VIOC_EC_FOUND m, o si destruyen el camion. Ya no saca a nadie, aviso a tu bando y el camion queda libre (sin
	    cerrar) como botin; las tiendas se quitan cuando no hay jugadores a 200 m.
	  - Las escuadras que ya salieron siguen peleando; una escuadra lejos de todos los jugadores (1,5 km) se borra a los
	    VIOC_EC_GROUP_TTL s.
	Gratis (no gasta dinero del enemigo). No se guardan (tampoco el camion: gancho en Server_SaveToProfile.sqf): al cargar una partida se vuelven a levantar con el tiempo.
	Parametros VIOC_ENEMY_CAMPS (0 no, 1-3 por bando) y VIOC_ENEMY_CAMPS_EVERY (min).
	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_EC_fnc_info);   call VIOC_EC_fnc_markers;   (marcadores locales)
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_EC_RUNNING") exitWith {};
VIOC_EC_RUNNING = true;
VIOC_EC_MAX = missionNamespace getVariable ["VIOC_ENEMY_CAMPS", 2];
if !(VIOC_EC_MAX isEqualType 0) then {VIOC_EC_MAX = 2};
if (VIOC_EC_MAX <= 0) exitWith {diag_log "[VIOC enemy_camps] desactivado por el parametro de lobby"};
VIOC_EC_EVERY = missionNamespace getVariable ["VIOC_ENEMY_CAMPS_EVERY", 8];
if !(VIOC_EC_EVERY isEqualType 0) then {VIOC_EC_EVERY = 8};
VIOC_EC_EVERY = (VIOC_EC_EVERY max 3) * 60;

//--- Ajustes
VIOC_EC_FIRST = 480;          // s de partida antes del primer campamento
VIOC_EC_NEW = 600;            // s entre campamentos nuevos de un bando
VIOC_EC_FOUND = 30;           // m: un soldado tuyo a pie a esta distancia = encontrado y destruido
VIOC_EC_SQUAD = 6;            // soldados por escuadra
VIOC_EC_CAP = 12;             // soldados vivos como mucho por campamento
VIOC_EC_NOSPAWN = 250;        // m: no sale nadie con soldados o vehiculos tuyos a esta distancia
VIOC_EC_SAFE = 700;           // m minimos a tus pueblos, HQ y estructuras al elegir el lugar
VIOC_EC_PLAYER_MIN = 600;     // m minimos a cualquier jugador al levantarlo
VIOC_EC_FRONT_R = 3500;       // m: solo pueblos del bando a esta distancia de lo tuyo
VIOC_EC_TARGET_R = 3000;      // m: pueblo tuyo que atacan las escuadras
VIOC_EC_HOLD_R = 2500;        // m: sin un pueblo del bando a esta distancia el campamento queda dormido
VIOC_EC_DORM = 600;           // s dormido (y sin jugadores a 1 km) antes de quitarlo
VIOC_EC_AI_MARGIN = 40;       // plazas del presupuesto de IA que se dejan libres
VIOC_EC_GROUP_TTL = 2700;     // s: escuadra lejos de los jugadores se borra a los 45 min
VIOC_EC_PERIOD = 15;          // s por pasada

VIOC_EC_CAMPS = [];
VIOC_EC_NEXT = [0, 0];        // por bando [oeste, este]: proximo campamento nuevo
VIOC_EC_POOLS = createHashMap;
VIOC_EC_INFO = [0, 0, 0];     // [campamentos levantados, escuadras salidas, campamentos destruidos]

//--- ---------------------------------- utilidades ----------------------------------
VIOC_EC_HUM = [];	//--- bandos que alguna vez tuvieron un jugador (no se olvidan si nadie esta conectado)
VIOC_EC_fnc_humans = {
	private _pl = allPlayers - (entities "HeadlessClient_F");
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	{
		private _s = side group _x;
		if (_s in [west, east]) then {VIOC_EC_HUM pushBackUnique _s};
	} forEach _pl;
	VIOC_EC_HUM
};

VIOC_EC_fnc_players = {
	private _pl = (allPlayers - (entities "HeadlessClient_F")) select {alive _x};
	if (!isMultiplayer && {hasInterface} && {!isNull player} && {alive player}) then {_pl pushBackUnique player};
	_pl
};

VIOC_EC_fnc_near = {
	params ["_p", "_r", "_pl"];
	(_pl findIf {(_x distance2D _p) < _r}) >= 0
};

VIOC_EC_fnc_rear = {
	params ["_t"];
	!isNil "VIOC_FL_fnc_isRear" && {[_t] call VIOC_FL_fnc_isRear}
};

VIOC_EC_fnc_say = {
	params ["_side", "_text"];
	[_text] remoteExec ["systemChat", _side];
};

//--- (como VIOC_AA_fnc_room) [hombres] -> true si caben en el presupuesto de IA (perf_cleanup; sin el, 650)
VIOC_EC_fnc_room = {
	params ["_n"];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", -1];
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
	if (!(_max isEqualType 0) || {!(_cnt isEqualType 0)} || {_max < 0} || {_cnt < 0}) then {_max = 650; _cnt = {!isPlayer _x} count allUnits};
	(_cnt + _n) <= (_max - VIOC_EC_AI_MARGIN)
};

//--- (como VIOC_AA_fnc_reserve) [hombres]: se suman al recuento de perf_cleanup hasta su proximo recuento
VIOC_EC_fnc_reserve = {
	params ["_n"];
	isNil {
		private _c = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
		if (_c isEqualType 0 && {_c >= 0}) then {VIOC_PERF_AI_COUNT = _c + _n};
	};
};

//--- [bando] -> [fusileros, ametralladores, antitanque]: listas de pueblo del bando (<BANDO>_INFANTRY_SQ_*)
VIOC_EC_fnc_pool = {
	params ["_side"];
	private _k = str _side;
	if (_k in VIOC_EC_POOLS) exitWith {VIOC_EC_POOLS get _k};
	private _tag = ["WEST_", "EAST_"] select (_side isEqualTo east);
	private _get = {
		params ["_n"];
		private _l = missionNamespace getVariable [_tag + _n, []];
		if !(_l isEqualType []) then {_l = []};
		private _r = [];
		{
			private _c = if (_x isEqualType []) then {_x param [0, ""]} else {_x};
			if ((_c isEqualType "") && {_c != ""} && {isClass (configFile >> "CfgVehicles" >> _c)} && {_c isKindOf "CAManBase"}) then {_r pushBackUnique _c};
		} forEach _l;
		_r
	};
	private _res = [["INFANTRY_SQ_LIGHT"] call _get, ["INFANTRY_SQ_MG"] call _get, ["INFANTRY_SQ_AT"] call _get];
	if (count (_res select 0) > 0) then {VIOC_EC_POOLS set [_k, _res]};
	_res
};

//--- [bando] -> clase del camion del campamento (de sus listas de ruedas; si no, uno de Arma) o ""
VIOC_EC_fnc_truck = {
	params ["_side"];
	private _tag = ["WEST_", "EAST_"] select (_side isEqualTo east);
	private _c = [];
	{
		private _l = missionNamespace getVariable [_tag + _x, []];
		if (_l isEqualType []) then {
			{
				private _k = if (_x isEqualType []) then {_x param [0, ""]} else {_x};
				if ((_k isEqualType "") && {_k != ""} && {isClass (configFile >> "CfgVehicles" >> _k)}) then {_c pushBackUnique _k};
			} forEach _l;
		};
	} forEach ["WHEELED_SQ_LIGHT", "WHEELED_SQ_HEAVY"];
	private _t = _c select {_x isKindOf "Truck_F"};
	if (count _t == 0) then {_t = _c select {(_x isKindOf "Car") && {getNumber (configFile >> "CfgVehicles" >> _x >> "transportSoldier") >= 4}}};
	if (count _t == 0) then {
		_t = (if (_side isEqualTo east) then {["O_Truck_02_transport_F", "O_G_Van_01_transport_F"]} else {["B_Truck_01_transport_F", "B_G_Van_01_transport_F"]}) select {isClass (configFile >> "CfgVehicles" >> _x)};
	};
	if (count _t == 0) exitWith {""};
	selectRandom _t
};

//--- [pueblo ancla, hacia, lo tuyo (posiciones), jugadores] -> lugar del campamento o []
VIOC_EC_fnc_site = {
	params ["_t", "_to", "_mine", "_pl"];
	private _c = getPosATL _t;
	private _dir = _c getDir _to;
	private _res = [];
	for "_i" from 0 to 79 do {
		private _sp = [50, 120] select (_i >= 40);
		private _q = _c getPos [400 + random 500, _dir - _sp + random (2 * _sp)];
		private _p = [_q select 0, _q select 1, 0];
		if (((_p select 0) > 50) && {(_p select 1) > 50} && {(_p select 0) < (worldSize - 50)} && {(_p select 1) < (worldSize - 50)}
			&& {!(surfaceIsWater _p)}
			&& {({surfaceIsWater (_p getPos [30, _x])} count [0, 90, 180, 270]) == 0}
			&& {(_p nearRoads 35) isEqualTo []}
			&& {(_mine findIf {(_x distance2D _p) < VIOC_EC_SAFE}) < 0}
			&& {!([_p, VIOC_EC_PLAYER_MIN, _pl] call VIOC_EC_fnc_near)}
			&& {(VIOC_EC_CAMPS findIf {((_x get "pos") distance2D _p) < 500}) < 0}
			&& {!((_p isFlatEmpty [-1, -1, 0.3, 10, 0, false]) isEqualTo [])}
			&& {(nearestTerrainObjects [_p, ["BUILDING", "HOUSE", "WALL", "FENCE", "ROCK", "ROCKS", "RUIN"], 15, false, true]) isEqualTo []}) exitWith {_res = _p};
	};
	_res
};

//--- [bando, lugar, pueblo ancla] -> campamento (HashMap) o [] si no cupo el camion
VIOC_EC_fnc_build = {
	params ["_side", "_p", "_anchor"];
	private _tc = [_side] call VIOC_EC_fnc_truck;
	if (_tc == "") exitWith {[]};
	private _tp = _p findEmptyPosition [0, 35, _tc];
	if (count _tp == 0) exitWith {[]};
	private _truck = createVehicle [_tc, _tp, [], 0, "NONE"];
	if (isNull _truck) exitWith {[]};
	_truck setDir (random 360);
	_truck setFuel 0.3;
	_truck lock 2;
	_truck setVariable ["VIOC_KEEP", true, true];
	_truck setVariable ["vioc_ec", true, true];
	_truck setVariable ["vioc_specops", true, true];	//--- perf_stuck y los demas sistemas no lo toman
	private _objs = [];
	private _put = {
		params ["_cls", "_dist", "_ang", ["_sim", false]];
		if !(isClass (configFile >> "CfgVehicles" >> _cls)) exitWith {objNull};
		private _q = (getPosATL _truck) getPos [_dist, (getDir _truck) + _ang];
		private _o = createVehicle [_cls, [_q select 0, _q select 1, 0], [], 0, "NONE"];
		if (isNull _o) exitWith {objNull};
		_o setDir ((getDir _truck) + _ang + 90);
		_o setVectorUp (surfaceNormal (getPosATL _o));
		if (!_sim) then {_o enableSimulationGlobal false};
		_o setVariable ["VIOC_KEEP", true];
		_o setVariable ["vioc_ec", true];
		_objs pushBack _o;
		_o
	};
	private _net = (switch (_side) do {case west: {["CamoNet_BLUFOR_open_F"]}; case east: {["CamoNet_OPFOR_open_F"]}; default {[]}}) + ["CamoNet_INDP_open_F"];
	[(_net select {isClass (configFile >> "CfgVehicles" >> _x)}) param [0, ""], 9, 90] call _put;
	["Land_TentA_F", 10, 200] call _put;
	["Land_TentA_F", 11, 235] call _put;
	[(["Land_WoodenCrate_01_stack_x3_F", "Land_WoodenBox_F", "Land_PaperBox_closed_F"] select {isClass (configFile >> "CfgVehicles" >> _x)}) param [0, ""], 6, 150] call _put;
	private _f = ["Land_Campfire_F", 7, 300, true] call _put;
	if (!isNull _f) then {_f inflame true};
	VIOC_EC_INFO set [0, (VIOC_EC_INFO select 0) + 1];
	createHashMapFromArray [["side", _side], ["pos", getPosATL _truck], ["anchor", _anchor], ["truck", _truck], ["objs", _objs],
		["groups", []], ["next", time + 90 + (random 90)], ["born", time], ["state", "active"], ["gone", 0],
		["name", _anchor getVariable ["cti_town_name", "un pueblo"]]]
};

//--- [escuadra, campamento, bandos humanos]: ataca tu pueblo del frente mas cercano (o patrulla alrededor del campamento)
VIOC_EC_fnc_orders = {
	params ["_g", "_cp", "_hum"];
	private _p = _cp get "pos";
	private _hids = _hum apply {_x call CTI_CO_FNC_GetSideID};
	private _best = objNull;
	private _bd = VIOC_EC_TARGET_R;
	{
		private _d = _x distance2D _p;
		if (_d < _bd && {(_x getVariable ["cti_town_sideID", -1]) in _hids} && {!([_x] call VIOC_EC_fnc_rear)}) then {_bd = _d; _best = _x};
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	{deleteWaypoint [_g, 0]} forEach (waypoints _g);
	_g setBehaviour "AWARE";
	_g setCombatMode "RED";
	_g setSpeedMode "NORMAL";
	if (!isNull _best) then {
		private _tp = getPosATL _best;
		private _w0 = _g addWaypoint [_tp getPos [200, _tp getDir _p], 30];
		_w0 setWaypointType "MOVE";
		_w0 setWaypointFormation "WEDGE";
		_w0 setWaypointCompletionRadius 40;
		private _w1 = _g addWaypoint [_tp, 40];
		_w1 setWaypointType "SAD";
		_w1 setWaypointBehaviour "COMBAT";
		_w1 setWaypointCompletionRadius 40;
		private _w2 = _g addWaypoint [_tp, 0];
		_w2 setWaypointType "MOVE";
		_w2 setWaypointCompletionRadius 15;
		private _wc = _g addWaypoint [_tp, 40];
		_wc setWaypointType "CYCLE";
		_g setCurrentWaypoint _w0;
		_g setVariable ["vioc_ec_target", _best getVariable ["cti_town_name", "?"]];
	} else {
		private _first = objNull;
		for "_i" from 0 to 2 do {
			private _w = _g addWaypoint [_p getPos [150 + random 250, (_i * 120) + random 60], 20];
			_w setWaypointType "MOVE";
			_w setWaypointSpeed "LIMITED";
			_w setWaypointCompletionRadius 30;
			if (_i == 0) then {_first = _w};
		};
		private _wc = _g addWaypoint [_p, 20];
		_wc setWaypointType "CYCLE";
		_g setCurrentWaypoint _first;
		_g setVariable ["vioc_ec_target", "patrulla"];
	};
};

//--- [campamento, bandos humanos] -> escuadra nueva (o grpNull)
VIOC_EC_fnc_squad = {
	params ["_cp", "_hum"];
	private _side = _cp get "side";
	([_side] call VIOC_EC_fnc_pool) params ["_li", "_mg", "_at"];
	if (count _li == 0) exitWith {grpNull};
	private _cls = [selectRandom _li];
	if (count _mg > 0) then {_cls pushBack (selectRandom _mg)};
	if (count _at > 0) then {_cls pushBack (selectRandom _at)};
	while {count _cls < VIOC_EC_SQUAD} do {_cls pushBack (selectRandom _li)};
	private _g = createGroup [_side, true];
	if (isNull _g) exitWith {grpNull};
	private _o = _cp get "pos";
	{
		private _q = _o getPos [15 + random 7, random 360];
		private _u = [_x, _g, [_q select 0, _q select 1, 0], _side, false, "NONE"] call CTI_CO_FNC_CreateUnit;
		if (!isNil "_u" && {_u isEqualType objNull} && {!isNull _u}) then {_u setVariable ["vioc_ec", true, true]};
	} forEach _cls;
	if (({alive _x} count (units _g)) == 0) exitWith {deleteGroup _g; grpNull};
	_g setVariable ["vioc_ec", true, true];
	_g setVariable ["vioc_specops", true, true];	//--- como el asalto aereo: ai_tactics, ai_transport, airfields y town_cleanup no la toman
	_g setVariable ["vioc_ec_born", time];
	[{alive _x} count (units _g)] call VIOC_EC_fnc_reserve;
	[_g, _cp, _hum] call VIOC_EC_fnc_orders;
	(_cp get "groups") pushBack _g;
	VIOC_EC_INFO set [1, (VIOC_EC_INFO select 1) + 1];
	diag_log format ["[VIOC enemy_camps] escuadra de %1 (%2 soldados) desde el campamento cerca de %3 hacia %4", _side, {alive _x} count (units _g), _cp get "name", _g getVariable ["vioc_ec_target", "?"]];
	_g
};

//--- [campamento, quien lo encontro (o objNull)]
VIOC_EC_fnc_found = {
	params ["_cp", "_by"];
	_cp set ["state", "found"];
	_cp set ["gone", time];
	private _t = _cp get "truck";
	private _free = alive _t;
	if (!isNull _t) then {
		_t setVariable ["VIOC_KEEP", nil, true];	//--- perf_cleanup ya puede borrarlo abandonado; sigue con vioc_ec: no se guarda
		_t setVariable ["vioc_specops", nil, true];
		if (_free) then {_t lock 0};
	};
	VIOC_EC_INFO set [2, (VIOC_EC_INFO select 2) + 1];
	private _txt = if (isNull _by) then {
		format ["Campamento enemigo cerca de %1 destruido: ya no saldran soldados de alli.", _cp get "name"]
	} else {
		format ["%1 encontro un campamento enemigo cerca de %2: destruido, ya no saldran soldados de alli%3.", name _by, _cp get "name", ["", " (el camion queda libre)"] select _free]
	};
	{[_x, _txt] call VIOC_EC_fnc_say} forEach (call VIOC_EC_fnc_humans);
	diag_log format ["[VIOC enemy_camps] %1", _txt];
};

//--- [bando, sideID, sideIDs humanos, jugadores, pueblos] -> true si levanto un campamento
VIOC_EC_fnc_tryNew = {
	params ["_side", "_sid", "_hids", "_pl", "_towns"];
	private _mine = (_towns select {(_x getVariable ["cti_town_sideID", -1]) in _hids}) apply {getPosATL _x};
	{
		private _s = (_x) call CTI_CO_FNC_GetSideFromID;
		private _hq = _s call CTI_CO_FNC_GetSideHQ;
		if (!isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq}) then {_mine pushBack (getPosATL _hq)};
		private _sts = _s call CTI_CO_FNC_GetSideStructures;
		if (!isNil "_sts" && {_sts isEqualType []}) then {{if (_x isEqualType objNull && {!isNull _x}) then {_mine pushBack (getPosATL _x)}} forEach _sts};
	} forEach _hids;
	if (count _mine == 0) exitWith {false};
	private _anc = _towns select {
		private _t = _x;
		((_t getVariable ["cti_town_sideID", -1]) == _sid) && {!([_t] call VIOC_EC_fnc_rear)}
		&& {(VIOC_EC_CAMPS findIf {((_x get "state") == "active") && {(_x get "anchor") isEqualTo _t}}) < 0}
	};
	private _keys = [];
	{
		private _t = _x;
		private _d = 1e9;
		{_d = _d min (_x distance2D _t)} forEach _mine;
		if (_d < VIOC_EC_FRONT_R) then {_keys pushBack [_d, _forEachIndex]};
	} forEach _anc;
	if (count _keys == 0) exitWith {false};
	_keys sort true;
	private _done = false;
	{
		if (!_done) then {
			private _t = _anc select (_x select 1);
			private _c = getPosATL _t;
			private _to = _mine select 0;
			{if ((_x distance2D _c) < (_to distance2D _c)) then {_to = _x}} forEach _mine;
			private _p = [_t, _to, _mine, _pl] call VIOC_EC_fnc_site;
			if (count _p > 0) then {
				private _cp = [_side, _p, _t] call VIOC_EC_fnc_build;
				if (_cp isEqualType createHashMap) then {
					VIOC_EC_CAMPS pushBack _cp;
					_done = true;
					diag_log format ["[VIOC enemy_camps] campamento de %1 cerca de %2 en %3 (camion %4)", _side, _cp get "name", mapGridPosition (_cp get "pos"), typeOf (_cp get "truck")];
				};
			};
		};
	} forEach (_keys select [0, 3]);
	_done
};

VIOC_EC_fnc_info = {
	private _l = [format ["Campamentos enemigos: %1 en la lista; levantados %2, escuadras %3, destruidos %4 (max %5 por bando, escuadra cada %6 min)", count VIOC_EC_CAMPS, VIOC_EC_INFO select 0, VIOC_EC_INFO select 1, VIOC_EC_INFO select 2, VIOC_EC_MAX, VIOC_EC_EVERY / 60]];
	{
		private _n = 0;
		{_n = _n + ({alive _x} count (units _x))} forEach (_x get "groups");
		_l pushBack format ["%1 cerca de %2 (%3): %4, %5 soldados vivos, proxima escuadra en %6 s", _x get "side", _x get "name", mapGridPosition (_x get "pos"), _x get "state", _n, round (((_x get "next") - time) max 0)];
	} forEach VIOC_EC_CAMPS;
	_l joinString "\n"
};

//--- Marcadores locales de los campamentos (prueba; en la maquina que lo ejecuta)
VIOC_EC_fnc_markers = {
	{deleteMarkerLocal _x} forEach (allMapMarkers select {(_x find "vioc_ec_mk_") == 0});
	{
		private _m = createMarkerLocal [format ["vioc_ec_mk_%1", _forEachIndex], _x get "pos"];
		_m setMarkerTypeLocal "mil_flag";
		_m setMarkerColorLocal (["ColorOrange", "ColorGrey"] select ((_x get "state") != "active"));
		_m setMarkerTextLocal format ["Campamento %1", _x get "name"];
	} forEach VIOC_EC_CAMPS;
	count VIOC_EC_CAMPS
};

//--- ---------------------------------- bucle ----------------------------------
waitUntil {sleep 2; !isNil "CTI_Init_Server" && {!isNil "CTI_InitTowns"}};
VIOC_EC_NEXT = [time + VIOC_EC_FIRST, time + VIOC_EC_FIRST + 120];
diag_log format ["[VIOC enemy_camps] activo: %1 por bando, escuadra cada %2 min", VIOC_EC_MAX, VIOC_EC_EVERY / 60];

while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
	private _hum = call VIOC_EC_fnc_humans;
	private _hids = _hum apply {_x call CTI_CO_FNC_GetSideID};
	private _pl = call VIOC_EC_fnc_players;
	private _towns = missionNamespace getVariable ["CTI_Towns", []];

	//--- campamentos: encontrados, escuadras nuevas, escuadras viejas
	{
		private _cp = _x;
		private _side = _cp get "side";
		private _p = _cp get "pos";
		if ((_cp get "state") == "active") then {
			private _found = (_p nearEntities [["CAManBase"], VIOC_EC_FOUND]) select {alive _x && {(side group _x) in _hum}};
			if ((count _found > 0) || {!alive (_cp get "truck")}) then {
				[_cp, _found param [0, objNull]] call VIOC_EC_fnc_found;
			} else {
				private _ssid = _side call CTI_CO_FNC_GetSideID;
				private _anc = _cp get "anchor";
				private _own = ((_towns findIf {((_x getVariable ["cti_town_sideID", -1]) == _ssid) && {(_x distance2D _p) < VIOC_EC_HOLD_R}}) >= 0)
					&& {!isNull _anc} && {(_anc getVariable ["cti_town_sideID", -1]) == _ssid} && {!([_anc] call VIOC_EC_fnc_rear)};
				if (_own) then {_cp set ["dorm", -1]} else {if ((_cp getOrDefault ["dorm", -1]) < 0) then {_cp set ["dorm", time]}};
				if (!_own && {(time - (_cp get "dorm")) > VIOC_EC_DORM} && {!([_p, 1000, _pl] call VIOC_EC_fnc_near)}) then {
					//--- dormido: se quita en silencio (deja libre el cupo del bando para otro en el frente de hoy)
					{if (!isNull _x) then {deleteVehicle _x}} forEach (_cp get "objs");
					_cp set ["objs", []];
					private _t = _cp get "truck";
					if (!isNull _t && {(count (crew _t)) == 0}) then {deleteVehicle _t};
					_cp set ["state", "removed"];
					diag_log format ["[VIOC enemy_camps] campamento cerca de %1 quitado (dormido)", _cp get "name"];
				};
				if (((_cp get "state") == "active") && {time >= (_cp get "next")}) then {
					private _alive = 0;
					{_alive = _alive + ({alive _x} count (units _x))} forEach (_cp get "groups");
					private _clear = ((_p nearEntities [["CAManBase", "LandVehicle"], VIOC_EC_NOSPAWN]) findIf {alive _x && {(side group _x) in _hum}}) < 0;
					private _g = grpNull;
					if (_own && {_clear} && {(_alive + VIOC_EC_SQUAD) <= VIOC_EC_CAP} && {[VIOC_EC_SQUAD] call VIOC_EC_fnc_room}) then {_g = [_cp, _hum] call VIOC_EC_fnc_squad};
					_cp set ["next", time + ([60, VIOC_EC_EVERY] select (!isNull _g))];
				};
			};
		} else {
			//--- encontrado: las tiendas se quitan sin jugadores a 200 m (o a los 15 min)
			if ((count (_cp get "objs") > 0) && {!([_p, 200, _pl] call VIOC_EC_fnc_near) || {time > ((_cp get "gone") + 900)}}) then {
				{if (!isNull _x) then {deleteVehicle _x}} forEach (_cp get "objs");
				_cp set ["objs", []];
			};
		};
		//--- escuadras: fuera las vacias; las viejas lejos de todos los jugadores se borran
		{
			private _g = _x;
			if ((!isNull _g) && {(time - (_g getVariable ["vioc_ec_born", time])) > VIOC_EC_GROUP_TTL} && {((units _g) findIf {alive _x && {[getPosATL _x, 1500, _pl] call VIOC_EC_fnc_near}}) < 0}) then {
				{deleteVehicle _x} forEach (units _g);
			};
		} forEach (_cp get "groups");
		_cp set ["groups", (_cp get "groups") select {(!isNull _x) && {({alive _x} count (units _x)) > 0}}];
	} forEach VIOC_EC_CAMPS;
	VIOC_EC_CAMPS = VIOC_EC_CAMPS select {((_x get "state") == "active") || {count (_x get "objs") > 0} || {count (_x get "groups") > 0}};

	//--- campamentos nuevos de cada bando enemigo
	{
		private _side = _x;
		private _si = [west, east] find _side;
		private _act = {((_x get "side") isEqualTo _side) && {(_x get "state") == "active"}} count VIOC_EC_CAMPS;
		if (_act < VIOC_EC_MAX && {time >= (VIOC_EC_NEXT select _si)}) then {
			private _ok = [_side, _side call CTI_CO_FNC_GetSideID, _hids, _pl, _towns] call VIOC_EC_fnc_tryNew;
			VIOC_EC_NEXT set [_si, time + ([120, VIOC_EC_NEW] select _ok)];
		};
	} forEach ([west, east] - _hum);
	sleep VIOC_EC_PERIOD;
};

