	title = "VIOC: Campamentos avanzados de la IA enemiga (camion y tiendas que sacan infanteria hasta que un soldado tuyo llegue a 30 m)";
	values[] = {0,1,2,3};
	texts[] = {"No","1 por bando","2 por bando","3 por bando"};
	default = 2;
